pub fn is_normalized(&self) -> bool {
    // Check if the URI has a valid scheme and authority
    if self.scheme.is_empty() || self.authority.is_none() {
        return false;
    }

    // Check if the path is normalized
    if !self.path.is_normalized() {
        return false;
    }

    // Check if the query is normalized (if it exists)
    if let Some(query) = &self.query {
        if !query.is_normalized() {
            return false;
        }
    }

    true
}

